css:
/* A4, measured from the paper original. Top-level .print-format margins are the
   wkhtmltopdf page margins (Frappe reads them); the Wahni artwork and the
   "N of 5" labels are stamped onto the PDF by wahni_solar_proposal/proposal_pdf.py. */
.print-format {
    margin-top: 42mm;
    margin-bottom: 22mm;
    margin-left: 24mm;
    /* 2mm less than the layout margin; see the print padding below */
    margin-right: 22mm;
    padding: 0 !important;
    font-family: "Times New Roman", "Liberation Serif", serif;
    font-size: 10.5pt;
    line-height: 14.4pt;
    color: #000;
}
/* Frappe reads only the top-level rule above; don't apply it again inside the page.
   The 2mm right inset absorbs wkhtmltopdf drawing text slightly wider than it laid it out,
   which otherwise clips the last letters of full-width lines at the page margin. */
@media print {
    .print-format { margin: 0 !important; }
    .document-page { padding-right: 2mm; }
    /* transparent, so the artwork stamped under each page shows through */
    html, body, .print-format-gutter, .print-format { background: transparent !important; }
}
.document-page { position: relative; }
.document-page + .document-page { page-break-before: always; }
.document-page p { margin: 0; text-align: justify; }
.document-page .center { text-align: center; margin: 1.3mm 0; }
.document-page .gap { margin-top: 1.3mm; }
/* numbered clauses: number in the gutter, wrapped lines aligned with the text */
.document-page .h, .document-page .bullet { padding-left: 12.7mm; }
.document-page .cl { padding-left: 19mm; }
.document-page .sub { padding-left: 29mm; }
.document-page .n { display: inline-block; text-align: left; }
.document-page .h .n, .document-page .bullet .n { width: 6.4mm; margin-left: -6.4mm; }
.document-page .cl .n { width: 9.1mm; margin-left: -9.1mm; }
.document-page .sub .n { width: 13mm; margin-left: -13mm; }
.document-page .indent { padding-left: 12.7mm; }
.document-page .signatures { width: 100%; border-collapse: collapse; margin-top: 3mm; line-height: 4.2mm; }
.document-page .signatures td { width: 50%; padding: 0 !important; vertical-align: top !important; border: 0; }
.document-page .signatures td + td { padding-left: 1mm !important; }
.document-page .signatures .space td { height: 12.5mm; }
.document-page .page-no { display: none; }
/* Browser preview: each page as an A4 sheet with the same margins and artwork. */
@media screen {
    .print-format {
        width: 210mm; max-width: none; min-height: 0;
        margin: 0 auto !important;
        background: transparent !important; box-shadow: none !important; border-radius: 0;
    }
    .document-page {
        box-sizing: border-box;
        width: 210mm;
        min-height: 297mm;
        padding: 42mm 24mm 22mm;
        margin: 0 auto 8mm;
        background: #fff url('/files/proposal_bg.png') top left / 210mm 297mm no-repeat;
        box-shadow: 0 1px 6px rgba(0, 0, 0, .25);
    }
    .document-page:first-child { background-image: url('/files/proposal_fp_bg.png'); }
    .document-page .page-no {
        display: block; position: absolute; left: 0; right: 0; top: 272.7mm;
        text-align: center; font-size: 12pt; line-height: 1;
    }
    .document-page:first-child .page-no { top: 266.7mm; }
}
